using System;using System.IO;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json;using Orbit;
class JournalTests {
 static int count;static string root=Path.Combine(Path.GetTempPath(),"orbit-journal-"+Guid.NewGuid());static string A=Guid.NewGuid().ToString(),B=Guid.NewGuid().ToString(),C=Guid.NewGuid().ToString();
 static void Check(bool condition,string name){if(!condition)throw new Exception(name);Console.WriteLine("PASS "+(++count)+" "+name);}static void Fails(Action a,string name){try{a();}catch{Check(true,name);return;}throw new Exception(name+" did not reject");}
 static Dictionary<string,long> R(GameJournal j,params string[] ids)=>ids.ToDictionary(id=>id,id=>j.Snapshot().entries.FirstOrDefault(e=>e.gameId==id)?.noteRevision??0);
 static string FileAt(string name)=>Path.Combine(root,name,"journal.json");
 static void Main(){Directory.CreateDirectory(root);try{var f=FileAt("normal");var j=new GameJournal(f);Check(j.Snapshot().entries.Length==0&&!j.Snapshot().readOnly,"fresh store");
 j.SetQueued(new[]{A,B},true,false,DateTime.UtcNow);Check(j.Snapshot().entries.Length==2&&j.Snapshot().entries[0].position==j.Snapshot().entries[1].position,"copies share queue position");
 j.SetNote(new[]{A,B},"Привет 🪐\r\nСохранение",R(j,A,B));Check(j.Snapshot().entries.All(e=>e.note=="Привет 🪐\nСохранение"),"Unicode shared note and newline normalization");
 var restart=new GameJournal(f);Check(restart.Snapshot().revision==j.Snapshot().revision&&restart.Snapshot().entries[0].note==j.Snapshot().entries[0].note,"restart persistence");
 var rev=R(j,A,B);j.SetQueued(new[]{C},true,false,DateTime.UtcNow);var date=j.Snapshot().entries.First(e=>e.gameId==A).queuedAt;j.SetQueued(new[]{A,B},true,true,DateTime.UtcNow.AddDays(1));Check(j.Snapshot().entries.First(e=>e.gameId==A).queuedAt==date&&j.Snapshot().entries.First(e=>e.gameId==A).position<j.Snapshot().entries.First(e=>e.gameId==C).position,"move first preserves date");
 j.SetNote(new[]{A,B},"Next",rev);Check(j.Snapshot().entries.First(e=>e.gameId==A).note=="Next","queue update does not conflict with note");
 Fails(()=>j.SetNote(new[]{A,B},"stale",rev),"stale revisions rejected");var before=File.ReadAllText(f);var bad=R(j,A,B);bad[B]=0;Fails(()=>j.SetNote(new[]{A,B},"partial",bad),"multi-copy stale save rejected");Check(File.ReadAllText(f)==before,"conflict makes no partial write");
 j.SetQueued(new[]{A,B},false,false,DateTime.UtcNow);Check(j.Snapshot().entries.Where(e=>e.gameId==A||e.gameId==B).All(e=>e.note=="Next"&&!e.queuedAt.HasValue),"removing queue preserves note");
 j.SetNote(new[]{A,B}," ",R(j,A,B));Check(!j.Snapshot().entries.Any(e=>e.gameId==A||e.gameId==B),"empty unused entries pruned");
 var snap=j.Snapshot();snap.entries[0].note="tamper";Check(j.Snapshot().entries[0].note!="tamper","snapshots detached");
 Fails(()=>j.SetNote(new[]{A},new string('a',4001),R(j,A)),"text limit");Fails(()=>j.SetNote(new[]{A},"bad\0value",R(j,A)),"control characters rejected");Fails(()=>j.SetQueued(new[]{"bad"},true,false,DateTime.UtcNow),"invalid game id rejected");Fails(()=>j.SetNote(new[]{A},"x",null),"missing CAS rejected");
 var fail=FileAt("blocked");Directory.CreateDirectory(Path.GetDirectoryName(fail));Directory.CreateDirectory(fail);var blocked=new GameJournal(fail);Fails(()=>blocked.SetQueued(new[]{A},true,false,DateTime.UtcNow),"write error surfaced");Check(blocked.Snapshot().entries.Length==0&&blocked.Snapshot().warning!=null,"failed write leaves memory intact");Directory.Delete(fail);blocked.SetQueued(new[]{A},true,false,DateTime.UtcNow);Check(blocked.Snapshot().warning==null,"recovery clears write warning");
 var backupFile=FileAt("backup");var backup=new GameJournal(backupFile);backup.SetNote(new[]{A},"old",R(backup,A));backup.SetNote(new[]{A},"new",R(backup,A));File.WriteAllText(backupFile,"invalid");var backupBytes=File.ReadAllText(backupFile+".bak");var recovered=new GameJournal(backupFile);Check(recovered.Snapshot().entries[0].note=="old"&&!recovered.Snapshot().readOnly,"backup restores corrupt primary");recovered.SetNote(new[]{A},"recovered",R(recovered,A));Check(File.ReadAllText(backupFile+".bak")==backupBytes,"good backup retained after recovery");
 File.WriteAllText(backupFile,"{\"schema\":2,\"revision\":9,\"entries\":[]}");var future=new GameJournal(backupFile);Check(future.Snapshot().readOnly,"future schema never downgraded to backup");Fails(()=>future.SetNote(new[]{A},"bad",R(future,A)),"future data not overwritten");
 File.Delete(backupFile);Check(new GameJournal(backupFile).Snapshot().entries[0].note=="old","missing primary uses backup");File.WriteAllText(backupFile,"{}");File.WriteAllText(backupFile+".bak","{}");Check(new GameJournal(backupFile).Snapshot().readOnly,"invalid primary and backup read only");
 var required=FileAt("required");Directory.CreateDirectory(Path.GetDirectoryName(required));File.WriteAllText(required,"{\"schema\":1}");Check(new GameJournal(required).Snapshot().readOnly,"required fields enforced");
 Check(!Directory.GetFiles(root,"*.tmp-*",SearchOption.AllDirectories).Any(),"no abandoned temporary files");Console.WriteLine("JournalTests: "+count+" passed");}finally{Directory.Delete(root,true);}}
}
